(6339516, 938290, 16148, '<td valign="top">Great lighting!</td>', 'Great lighting!', '2011-03-02 19:17:51.000000', NULL, 1),
(6339660, 937989, 125659, '<td valign="top">Great contrast and sharpness!</td>', 'Great contrast and sharpness!', '2011-03-02 21:15:02.000000', NULL, 1),
(6339662, 937752, 125659, '<td valign="top">Really cool idea and great contrast</td>', 'Really cool idea and great contrast', '2011-03-02 21:16:13.000000', NULL, 1),
(6339671, 938091, 125659, '<td valign="top">Great photo. I personally would like it more if the eye was sharper. Seems a little grainy. Very cool idea though.</td>', 'Great photo. I personally would like it more if the eye was sharper. Seems a little grainy. Very cool idea though.', '2011-03-02 21:23:54.000000', NULL, 1),
