(6339676, 938283, 125659, '<td valign="top">Really sharp eye. Not too sure of the lighting. Did you use a diffuser on the flash?</td>', 'Really sharp eye. Not too sure of the lighting. Did you use a diffuser on the flash?', '2011-03-02 21:27:42.000000', NULL, 1),
(6339677, 938270, 125659, '<td valign="top">Nice macro. Very sharp.</td>', 'Nice macro. Very sharp.', '2011-03-02 21:28:25.000000', NULL, 1),
(6339683, 938285, 125659, '<td valign="top">Great photo. I think it would look better if the lighting wasn''t as bright however.</td>', 'Great photo. I think it would look better if the lighting wasn''t as bright however.', '2011-03-02 21:32:10.000000', NULL, 1),
(6339829, 937888, 15511, '<td valign="top">The irresponsibility of all persons involved in this image leaves me wondering whether Ma is even aware...</td>', 'The irresponsibility of all persons involved in this image leaves me wondering whether Ma is even aware...', '2011-03-03 00:13:09.000000', NULL, 1),
