(6340065, 937833, 67665, '<td valign="top">Half full</td>', 'Half full', '2011-03-03 10:30:41.000000', NULL, 1),
(6340091, 937824, 3585, '<td valign="top">half a score   5   ( and I suppose I''m not the first one lured by your title)</td>', 'half a score   5   ( and I suppose I''m not the first one lured by your title)', '2011-03-03 11:10:32.000000', NULL, 1),
(6340092, 937903, 3585, '<td valign="top">Nice</td>', 'Nice', '2011-03-03 11:11:52.000000', NULL, 1),
(6340094, 938101, 3585, '<td valign="top">This works rather well, a little too orderly to inspire me though. A detail to bring it to life would have been welcome; a small defect , a lazy fly, one or two fingers through the shades etc.  7</td>', 'This works rather well, a little too orderly to inspire me though. A detail to bring it to life would have been welcome; a small defect , a lazy fly, one or two fingers through the shades etc.  7', '2011-03-03 11:18:04.000000', NULL, 1),
(6340096, 938061, 3585, '<td valign="top">That must be impressive!</td>', 'That must be impressive!', '2011-03-03 11:19:48.000000', NULL, 1),
(6340097, 937908, 19825, '<td valign="top">Cats are a popular subject for challenges. Not being much of a cat person they tend to go by pretty quickly as I am voting. However, your cat picture is stunning. I think it is a perfect shot/subject for this challenge with that single green eye staring you down. Very nice shot.</td>', 'Cats are a popular subject for challenges. Not being much of a cat person they tend to go by pretty quickly as I am voting. However, your cat picture is stunning. I think it is a perfect shot/subject for this challenge with that single green eye staring you down. Very nice shot.', '2011-03-03 11:21:05.000000', NULL, 1),
(6340195, 938285, 108580, '<td valign="top">I get it...does anyone else? Nice and soft too btw.</td>', 'I get it...does anyone else? Nice and soft too btw.', '2011-03-03 14:23:45.000000', NULL, 1),
(6340196, 937407, 108580, '<td valign="top">Extremely appealing crop/composition. I love it. Smooth mostly white BG adds a superb 3D feel and dimension.</td>', 'Extremely appealing crop/composition. I love it. Smooth mostly white BG adds a superb 3D feel and dimension.', '2011-03-03 14:25:16.000000', NULL, 1),
(6340200, 938303, 108580, '<td valign="top">I love the light on this. It''s not bursting with colour and contrast. Almost appears ambient window light. Great! Super focus and texture</td>', 'I love the light on this. It''s not bursting with colour and contrast. Almost appears ambient window light. Great! Super focus and texture', '2011-03-03 14:26:57.000000', NULL, 1),
(6340202, 937867, 108580, '<td valign="top">Wonderful light and contrast. Great PP and composition</td>', 'Wonderful light and contrast. Great PP and composition', '2011-03-03 14:27:40.000000', NULL, 1),
(6340235, 938301, 108580, '<td valign="top">Really great HD style work, not overdone, crisp, smooth, noiseless.</td>', 'Really great HD style work, not overdone, crisp, smooth, noiseless.', '2011-03-03 14:55:30.000000', NULL, 1),
(6340236, 938131, 108580, '<td valign="top">Soft, smooth, appealing, like silk</td>', 'Soft, smooth, appealing, like silk', '2011-03-03 14:57:59.000000', NULL, 1),
(6340251, 937796, 56502, '<td valign="top">Interesting light setup for this shot.</td>', 'Interesting light setup for this shot.', '2011-03-03 15:27:22.000000', NULL, 1),
